class Solution:
    def largestValues(self, root):
        if not root: return []
        q=deque([root]);out=[]
        while q:
            best=float('-inf')
            for _ in range(len(q)):
                node=q.popleft();best=max(best,node.val)
                if node.left:q.append(node.left)
                if node.right:q.append(node.right)
            out.append(best)
        return out

import java.util.*;
class Solution {
    public List<Integer> largestValues(TreeNode root) {
        List<Integer> out=new ArrayList<>();if(root==null)return out;
        Queue<TreeNode> q=new ArrayDeque<>();q.add(root);
        while(!q.isEmpty()){int size=q.size(),best=Integer.MIN_VALUE;for(int i=0;i<size;i++){TreeNode n=q.remove();best=Math.max(best,n.val);if(n.left!=null)q.add(n.left);if(n.right!=null)q.add(n.right);}out.add(best);}
        return out;
    }
}

