class Solution:
    def findLUSlength(self, strs: list[str]) -> int:
        def is_sub(a,b):
            i=0
            for c in b:
                if i<len(a) and a[i]==c: i+=1
            return i==len(a)
        for i in sorted(range(len(strs)),key=lambda i:len(strs[i]),reverse=True):
