    public int findLUSlength(String[] strs){Integer[] idx=new Integer[strs.length];for(int i=0;i<idx.length;i++)idx[i]=i;Arrays.sort(idx,(i,j)->Integer.compare(strs[j].length(),strs[i].length()));for(int i:idx){boolean ok=true;for(int j=0;j<strs.length;j++)if(i!=j&&isSub(strs[i],strs[j])){ok=false;break;}if(ok)return strs[i].length();}return -1;}
}

class Solution:
