class Solution:
    def findMaxLength(self, nums: list[int]) -> int:
        first={0:-1};balance=best=0
        for i,x in enumerate(nums):
            balance += 1 if x==1 else -1
            if balance in first: best=max(best,i-first[balance])
            else:first[balance]=i
        return best

import java.util.*;
class Solution {
    public int findMaxLength(int[] nums){Map<Integer,Integer> first=new HashMap<>();first.put(0,-1);int bal=0,best=0;for(int i=0;i<nums.length;i++){bal+=nums[i]==1?1:-1;if(first.containsKey(bal))best=Math.max(best,i-first.get(bal));else first.put(bal,i);}return best;}
}

class Solution:
    def countArrangement(self, n: int) -> int:
        used=[False]*(n+1)
        def dfs(pos):
            if pos>n:return 1
            total=0
            for x in range(1,n+1):
                if not used[x] and (x%pos==0 or pos%x==0):
                    used[x]=True;total+=dfs(pos+1);used[x]=False
            return total
        return dfs(1)

class Solution {
    private int n;private boolean[] used;
    public int countArrangement(int n){this.n=n;used=new boolean[n+1];return dfs(1);}
    private int dfs(int pos){if(pos>n)return 1;int total=0;for(int x=1;x<=n;x++)if(!used[x]&&(x%pos==0||pos%x==0)){used[x]=true;total+=dfs(pos+1);used[x]=false;}return total;}
}
